SELECT ?point ?ts_id WHERE {
  ?zone a brick:Zone ;
        rdfs:label "Basement" .
  ?point brick:isPointOf ?zone ;
         ref:hasTimeseriesId ?ts_id .
  ?point a ?type .
  FILTER(contains(str(?type), "Occupancy") || contains(str(?type), "Person"))
}

SELECT ?point ?ts_id ?type WHERE {
  ?zone a brick:Zone ;
        rdfs:label "Basement" .
  ?point brick:isPointOf ?zone .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts_id . }
  OPTIONAL { ?point a ?type . }
}

SELECT ?zone WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "basement"))
}

